from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject
from taf.gnb.oam.coam.vdu.schemas.asm.dist_names import DistNames


class SFPMaxTransmissionDistance(SchemaObject):
    max_link_length_type = SchemaField(name='maxLinkLengthType', optional=True)
    max_link_length = SchemaField(name='maxLinkLength', optional=True)

    def __init__(self, max_link_length_type, max_link_length):
        self.max_link_length_type = max_link_length_type
        self.max_link_length = max_link_length

        super(SFPMaxTransmissionDistance, self).__init__()


class EmDynamicDataForLane(SchemaObject):
    lane_r_id = SchemaField(name='laneRId', optional=True)
    tx_supply_voltage = SchemaField(name='txSupplyVoltage', optional=True)
    tx_bias_current = SchemaField(name='txBiasCurrent', optional=True)
    tx_optical_power_dbm = SchemaField(name='txOpticalPowerDbm', optional=True)
    rx_optical_power_dbm = SchemaField(name='rxOpticalPowerDbm', optional=True)
    tx_optical_power_uw = SchemaField(name='txOpticalPowerUw', optional=True)
    rx_optical_power_uw = SchemaField(name='rxOpticalPowerUw', optional=True)
    lcv = SchemaField(name='lcv', optional=True)
    lcv_trend = SchemaField(name='lcvTrend', optional=True)
    ber = SchemaField(name='ber', optional=True)
    ber_trend = SchemaField(name='berTrend', optional=True)
    bit_error_rate_for24h = SchemaField(name='bitErrorRateFor24h', optional=True)
    module_temperature = SchemaField(name='moduleTemperature', optional=True)
    bits_received_for60s = SchemaField(name='bitsReceivedFor60s', optional=True)

    def __init__(self, lane_r_id, tx_supply_voltage, tx_bias_current, tx_optical_power_dbm, rx_optical_power_dbm,
                 tx_optical_power_uw, rx_optical_power_uw, lcv, lcv_trend, ber, ber_trend, bit_error_rate_for24h,
                 module_temperature, bits_received_for60s):
        self.lane_r_id = lane_r_id
        self.tx_supply_voltage = tx_supply_voltage
        self.tx_bias_current = tx_bias_current
        self.tx_optical_power_dbm = tx_optical_power_dbm
        self.rx_optical_power_dbm = rx_optical_power_dbm
        self.tx_optical_power_uw = tx_optical_power_uw
        self.rx_optical_power_uw = rx_optical_power_uw
        self.lcv = lcv
        self.lcv_trend = lcv_trend
        self.ber = ber
        self.ber_trend = ber_trend
        self.bit_error_rate_for24h = bit_error_rate_for24h
        self.module_temperature = module_temperature
        self.bits_received_for60s = bits_received_for60s

        super(EmDynamicDataForLane, self).__init__()


class PeerSfp(SchemaObject):
    dist_name = SchemaField(name='distName', optional=True)
    lane_r_id = SchemaField(name='laneRId', optional=True)
    peer_lane_r_id = SchemaField(name='peerLaneRId', optional=True)
    connected_link = SchemaField(name='connectedLink', optional=True)
    link_speed = SchemaField(name='linkSpeed', optional=True)
    fiber_length = SchemaField(name='fiberLength', optional=True)
    link_type = SchemaField(name='linkType', optional=True)

    def __init__(self, dist_name, lane_r_id, peer_lane_r_id, connected_link, link_speed, fiber_length, link_type):
        self.dist_name = dist_name
        self.lane_r_id = lane_r_id
        self.peer_lane_r_id = peer_lane_r_id
        self.connected_link = connected_link
        self.link_speed = link_speed
        self.fiber_length = fiber_length
        self.link_type = link_type

        super(PeerSfp, self).__init__()


class DiagnosticInfoFromSFPConnectionASMV2(SchemaObject):
    compliance_code = SchemaField(name="complianceCode", optional=True)
    connector_type = SchemaField(name="connectorType")
    cooled_transceiver_declaration = SchemaField(name="cooledTransceiverDeclaration", optional=True)
    diagnostic_monitoring_type = SchemaField(name="diagnosticMonitoringType", optional=True)
    manufacturing_date = SchemaField(name="manufacturingDate", optional=True)
    physical_port = SchemaField(name="physicalPort", optional=True)
    product_code = SchemaField(name="productCode", optional=True)

    rx_power_high_alarm_threshold = SchemaField(name="rxPowerHighAlarmThreshold")
    rx_power_high_warn_threshold = SchemaField(name="rxPowerHighWarnThreshold", optional=True)
    rx_power_low_alarm_threshold = SchemaField(name="rxPowerLowAlarmThreshold", optional=True)
    rx_power_low_warn_threshold = SchemaField(name="rxPowerLowWarnThreshold", optional=True)
    serial_number = SchemaField(name="serialNumber", optional=True)
    sfp_nominal_transmission_rate = SchemaField(name="sfpNominalTransmissionRate", optional=True)
    sfp_port = SchemaField(name="sfpPort", not_null=True)

    sfp_wavelength = SchemaField(name="sfpWavelength", optional=True)
    temperature_high_alarm_threshold = SchemaField(name="temperatureHighAlarmThreshold")
    temperature_low_alarm_threshold = SchemaField(name="temperatureLowAlarmThreshold", optional=True)
    transceiver_compliance_code = SchemaField(name="transceiverComplianceCode", optional=True)
    transceiver_identifier = SchemaField(name="transceiverIdentifier", optional=True)
    tx_power_high_alarm_threshold = SchemaField(name="txPowerHighAlarmThreshold")

    tx_power_high_warn_threshold = SchemaField(name="txPowerHighWarnThreshold", optional=True)
    tx_power_low_alarm_threshold = SchemaField(name="txPowerLowAlarmThreshold")
    tx_power_low_warn_threshold = SchemaField(name="txPowerLowWarnThreshold", optional=True)
    vendor_name = SchemaField(name="vendorName", optional=True)
    vendor_part_number = SchemaField(name="vendorPartNumber", optional=True)
    vendor_revision = SchemaField(name="vendorRevision", optional=True)
    nokia_part_number = SchemaField(name='nokiaPartNumber', optional=True)
    sfp_nominal_signaling_rate = SchemaField(name='sfpNominalSignalingRate', optional=True)
    max_transmission_distance = SchemaField(name='maxTransmissionDistance', optional=True, many=True,
                                            klass=SFPMaxTransmissionDistance)
    dynamic_data_for_lane = SchemaField(name='dynamicDataForLane', optional=True, many=True,
                                        klass=EmDynamicDataForLane)
    peer_sf_ps = SchemaField(name='peerSfPs', optional=True, many=True, klass=PeerSfp)
    dist_names = SchemaField(name='distNames', optional=True, klass=DistNames)

    def __init__(self, compliance_code=None, connector_type=None, cooled_transceiver_declaration=None,
                 diagnostic_monitoring_type=None, manufacturing_date=None,
                 physical_port=None, product_code=None,
                 rx_power_high_alarm_threshold=None, rx_power_high_warn_threshold=None,
                 rx_power_low_alarm_threshold=None, rx_power_low_warn_threshold=None, serial_number=None,
                 sfp_nominal_transmission_rate=None, sfp_port=None, sfp_wavelength=None,
                 temperature_high_alarm_threshold=None, temperature_low_alarm_threshold=None,
                 transceiver_compliance_code=None, transceiver_identifier=None, tx_power_high_alarm_threshold=None,
                 tx_power_high_warn_threshold=None, tx_power_low_alarm_threshold=None, tx_power_low_warn_threshold=None,
                 vendor_name=None, vendor_part_number=None, vendor_revision=None, nokia_part_number=None,
                 sfp_nominal_signaling_rate=None, max_transmission_distance=None, dynamic_data_for_lane=None,
                 peer_sf_ps=None, dist_names=None
                 ):
        self.compliance_code = compliance_code
        self.connector_type = connector_type
        self.cooled_transceiver_declaration = cooled_transceiver_declaration
        self.diagnostic_monitoring_type = diagnostic_monitoring_type
        self.manufacturing_date = manufacturing_date
        self.physical_port = physical_port
        self.product_code = product_code
        self.rx_power_high_alarm_threshold = rx_power_high_alarm_threshold
        self.rx_power_high_warn_threshold = rx_power_high_warn_threshold
        self.rx_power_low_alarm_threshold = rx_power_low_alarm_threshold
        self.rx_power_low_warn_threshold = rx_power_low_warn_threshold
        self.serial_number = serial_number
        self.sfp_nominal_transmission_rate = sfp_nominal_transmission_rate
        self.sfp_port = sfp_port
        self.sfp_wavelength = sfp_wavelength
        self.temperature_high_alarm_threshold = temperature_high_alarm_threshold
        self.temperature_low_alarm_threshold = temperature_low_alarm_threshold
        self.transceiver_compliance_code = transceiver_compliance_code
        self.transceiver_identifier = transceiver_identifier
        self.tx_power_high_alarm_threshold = tx_power_high_alarm_threshold
        self.tx_power_high_warn_threshold = tx_power_high_warn_threshold
        self.tx_power_low_alarm_threshold = tx_power_low_alarm_threshold
        self.tx_power_low_warn_threshold = tx_power_low_warn_threshold
        self.vendor_name = vendor_name
        self.vendor_part_number = vendor_part_number
        self.vendor_revision = vendor_revision
        self.nokia_part_number = nokia_part_number
        self.sfp_nominal_signaling_rate = sfp_nominal_signaling_rate
        self.max_transmission_distance = max_transmission_distance
        self.dynamic_data_for_lane = dynamic_data_for_lane
        self.peer_sf_ps = peer_sf_ps
        self.dist_names = dist_names

        super(DiagnosticInfoFromSFPConnectionASMV2, self).__init__()
